  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" 
  PARTITION BY RANGE ("TXN_DATE") 
 (PARTITION "P202606"  VALUES LESS THAN ('20260701') , 
 PARTITION "P202607"  VALUES LESS THAN ('20260801') , 
 PARTITION "P202608"  VALUES LESS THAN ('20260901') , 
 PARTITION "P202609"  VALUES LESS THAN ('20261001') , 
 PARTITION "P202610"  VALUES LESS THAN ('20261101') , 
 PARTITION "P202611"  VALUES LESS THAN ('20261201') , 
 PARTITION "P202612"  VALUES LESS THAN ('20270101') , 
 PARTITION "P_MAX"  VALUES LESS THAN (MAXVALUE) ) ;
  CREATE UNIQUE INDEX "UK_GATE_TXN_PAY_BIZ" ON "GATE_TXN_PAY" ("CARD_ID", "TRX_TYPE", "OUT_TIME", "TICKET_TRANS_SEQ", "DEVICE_ID", "TXN_DATE") 
   LOCAL
 (PARTITION "P202606" NOCOMPRESS , 
 PARTITION "P202607" NOCOMPRESS , 
 PARTITION "P202608" NOCOMPRESS , 
 PARTITION "P202609" NOCOMPRESS , 
 PARTITION "P202610" NOCOMPRESS , 
 PARTITION "P202611" NOCOMPRESS , 
 PARTITION "P202612" NOCOMPRESS , 
 PARTITION "P_MAX" NOCOMPRESS ) ;
ALTER TABLE "GATE_TXN_PAY" ADD CONSTRAINT "UK_GATE_TXN_PAY_BIZ_KEY" UNIQUE ("CARD_ID", "TRX_TYPE", "OUT_TIME", "TICKET_TRANS_SEQ", "DEVICE_ID", "TXN_DATE")
  USING INDEX "UK_GATE_TXN_PAY_BIZ"  ENABLE;

