CREATE UNIQUE INDEX "UK_UIRI_ACTIVE_USER_CARDTYPE" ON "USER_ITP_REG_INFO" (CASE  WHEN ("DEL_YN"=1 AND ("TICKET_LIMIT"='1' OR ("TICKET_LIMIT" IS NULL AND NVL("COMPANION_FLAG",'N')<>'Y' AND NVL("COMPANION_FLAG",'N')<>'C'))) THEN "THIRD_USER_ID" END , CASE  WHEN ("DEL_YN"=1 AND ("TICKET_LIMIT"='1' OR ("TICKET_LIMIT" IS NULL AND NVL("COMPANION_FLAG",'N')<>'Y' AND NVL("COMPANION_FLAG",'N')<>'C'))) THEN "ISSUE_ORG_CODE" END , CASE  WHEN ("DEL_YN"=1 AND ("TICKET_LIMIT"='1' OR ("TICKET_LIMIT" IS NULL AND NVL("COMPANION_FLAG",'N')<>'Y' AND NVL("COMPANION_FLAG",'N')<>'C'))) THEN "CARD_TYPE" END ) 
  ;

