  ;


-- ==================== 第 3 部分: 表与字段注释 ====================

COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."ID" IS '主键，取 SEQ_ACCOUNT_EXCEPTION_TICKET';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."TICKET_TYPE" IS '工单类型，如 SIGN_SYNC_RETRY_EXHAUSTED-签约展示账号同步重试超限';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."BIZ_KEY" IS '业务幂等键，与 TICKET_TYPE 组成唯一索引；SIGN_SYNC_RETRY_EXHAUSTED 用 USER_PHONE_CHANGE_LOG.ID';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."THIRD_USER_ID" IS '第三方用户标识，便于按用户排查，允许为空';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."TICKET_STATUS" IS '工单状态，OPEN-待处理、CLOSED-已处理';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."RETRY_COUNT" IS '开单时已重试次数';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."DETAIL" IS '开单原因与现场信息快照，NEVER 写入密钥等敏感信息';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."CREATE_TMS" IS '开单时间';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."CLOSE_TMS" IS '关单时间';
   COMMENT ON COLUMN "ACCOUNT_EXCEPTION_TICKET"."CLOSED_BY" IS '关单人';
   COMMENT ON TABLE "ACCOUNT_EXCEPTION_TICKET"  IS '账户域异常工单表。补偿重试达上限等无法自愈的情况在此留一条待人工处理的记录。本表由 account-server 独占，其它域 NEVER 写入，各域应建自己的同类表';

COMMENT ON COLUMN "AGM_DEVICE_STATUS"."DEVICE_ID" IS '设备号';
   COMMENT ON COLUMN "AGM_DEVICE_STATUS"."STATION_CODE" IS '设备所在车站编码，由 deviceId 前 4 位解析';
   COMMENT ON COLUMN "AGM_DEVICE_STATUS"."LAST_HEARTBEAT_TMS" IS '最近一次心跳时间';
   COMMENT ON COLUMN "AGM_DEVICE_STATUS"."HEARTBEAT_COUNT" IS '累计心跳次数';
   COMMENT ON COLUMN "AGM_DEVICE_STATUS"."ONLINE_FLAG" IS '1 在线，0 离线';
   COMMENT ON TABLE "AGM_DEVICE_STATUS"  IS 'AGM 闸机最新心跳状态，一设备一行，用 MERGE INTO 更新；只存最新状态不存历史';

COMMENT ON COLUMN "ALIPAY_CARD_POOL"."CARD_ID" IS '逻辑卡号（主键）';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."THIRD_USER_ID" IS '支付宝用户ID';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."STATUS" IS '卡号状态（UNALLOCATED:未分配/ALLOCATED:已分配/USED:已使用）';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."INSERT_TMS" IS '插入时间';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."REG_TMS" IS '注册时间';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."DELETE_FLAG" IS '删除标记（0:正常 1:删除）';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."VERSION" IS '乐观锁版本号';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."CREATE_TIME" IS '创建时间';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."UPDATE_TIME" IS '更新时间';
   COMMENT ON COLUMN "ALIPAY_CARD_POOL"."CREATE_BY" IS '创建人';
   COMMENT ON TABLE "ALIPAY_CARD_POOL"  IS '支付宝卡号池表';

COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."TOTAL_AMOUNT" IS '支付中心口径的订单总金额（分），来自 payQuery 同步应答的 totalAmount 键；与本表 TRANS_AMOUNT（支付宝报文原文字符串）不是同一口径，NEVER 合并';
   COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."TXN_DATE" IS '订单日期 yyyyMMdd，取自主表 GATE_TXN_PAY.TXN_DATE，供按账期检索；本表当前未分区，NEVER 把它当分区键用';
   COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."RAW_BODY" IS '回调整包报文原文；2026-09-18 由 VARCHAR2(4000) 改为 CLOB，截断后的报文不再可举证';
   COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."REFUND_ORDER_NO" IS '退款单号，与 ALIPAY_REFUND_LOG.REFUND_ORDER_NO 同源；CALLBACK_TYPE=REFUND 时有值';
   COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."REFUND_AMOUNT" IS '退款金额（分），支付中心回调回传值';
   COMMENT ON COLUMN "ALIPAY_PAY_CALLBACK_LOG"."REFUND_STATUS" IS '退款状态，支付中心回调回传值；当前只落证据不回写业务';
   COMMENT ON TABLE "ALIPAY_PAY_CALLBACK_LOG"  IS '支付宝出行支付结果回调凭据表';

COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."ORDER_NO" IS '地铁侧订单号，等于 GATE_TXN_PAY.ORDER_NO 与 ALIPAY_PAY_TXN_DETAIL.ORDER_NO';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."TXN_DATE" IS '订单日期 yyyyMMdd，月分区键；取自主表，NEVER 用本地当天日期另算';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."API_NAME" IS '支付中心接口名：requestPay 扣款，payQuery 支付结果查询，requestRefund 退款申请，refundQuery 退款结果查询';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."REQUEST_NO" IS '本次请求的从键：退款类接口填退款单号，支付类接口留空';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."SCENE" IS '支付场景，我方送出的请求参数原值';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."INDUSTRY_TYPE" IS '行业类型：1地铁，2公交，3打车，4购物';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."IP_ADDRESS" IS '发起支付的用户 IP，审计用';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."RET_CODE" IS '支付中心本次同步应答的业务码；调用抛异常拿不到应答时留空，成因记在 REMARK';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."RET_MSG" IS '支付中心本次同步应答文案；NEVER 把它当 debitRequestResult 直接对外返回';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."ELAPSED_MS" IS '本次调用耗时毫秒，用于定位支付中心慢响应';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."REQUEST_BODY" IS '我方送出的请求报文原文，MUST 写；支付明细表删掉的 subject / body / authCode / notifyUrl / returnUrl / orderTimeOut 都在这里';
   COMMENT ON COLUMN "ALIPAY_PAY_CENTER_MSG_LOG"."RESPONSE_BODY" IS '支付中心同步应答报文原文；异步回调的原文在 ALIPAY_PAY_CALLBACK_LOG.RAW_BODY，两者不是一回事';
   COMMENT ON TABLE "ALIPAY_PAY_CENTER_MSG_LOG"  IS '支付宝出行渠道我方出网报文留痕表；一次调用一行，追加型流水，无唯一索引，NEVER 拿它推断订单当前状态';

COMMENT ON COLUMN "ALIPAY_PAY_LOG"."PAY_SEQ" IS '支付流水号（主键）';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."THIRD_USER_ID" IS '支付宝用户ID';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."ORDER_NO" IS '订单号';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."TRADE_NO" IS '支付宝交易号';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."PAY_AMOUNT" IS '支付金额（分）';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."PAY_STATUS" IS '支付状态（SUCCESS/FAIL）';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."PAY_TYPE" IS '支付类型';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."SCENE" IS '支付类型/场景';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."PAYMENT_VENDOR" IS '支付方式';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."INDUSTRY_TYPE" IS '行业类型：1-地铁 2-公交 3-打车 4-购物';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."SUBJECT" IS '订单标题';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."BODY" IS '订单描述';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."REQUEST_SIGN_SEQ" IS '签约流水号（免密场景）';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."ORDER_TIME_OUT" IS '订单超时时间（秒）';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."AUTH_CODE" IS '授权码';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."NOTIFY_URL" IS '回调地址';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."RETURN_URL" IS '返回前端页面地址';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."IP_ADDRESS" IS '用户IP地址';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."INDUSTRY_DETAIL" IS '行业详情，json格式';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."REQUEST_BODY" IS '原始请求报文';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."RESPONSE_BODY" IS '原始响应报文';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."RESULT_CODE" IS '响应码';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."RESULT_MSG" IS '响应信息';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."REMARK" IS '备注';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."ENTRY_ID" IS '进站交易id';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."EXIT_ID" IS '出站交易id';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."INVOICE" IS '发票状态';
   COMMENT ON COLUMN "ALIPAY_PAY_LOG"."TRANS_TIME" IS '交易时间（yyyy-MM-dd HH:mm:ss）';
   COMMENT ON TABLE "ALIPAY_PAY_LOG"  IS '支付宝支付流水表';

COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."ORDER_NO" IS '地铁侧订单号，等于 GATE_TXN_PAY.ORDER_NO，同时作为支付中心接口的 orderNo；本表唯一的对外查询键';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."TXN_DATE" IS '订单日期 yyyyMMdd，月分区键 + 唯一键第二列；取 GATE_TXN_PAY.TXN_DATE，NEVER 用本地当天日期另算';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."PAY_STATUS" IS '本笔在支付中心侧的状态：INIT初始化，PROCESSING处理中，SUCCESS成功，FAIL失败，RETRY待重试，CLOSED关闭；订单整体是否扣费成功以 GATE_TXN_PAY.DEBIT_STATUS 为准';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."AMOUNT" IS '我方送出的请求支付金额（分），恒有值；本表唯一的金额列，退款可退上限只取它。对端回传的金额在 ALIPAY_PAY_CALLBACK_LOG';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."REFUND_STATUS" IS '退款状态：NONE未退款，PROCESSING退款中，PARTIAL部分退款，SUCCESS已全额退款，FAIL退款失败';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."REFUND_AMOUNT" IS '已退款总金额（分），由 ALIPAY_REFUND_TXN_DETAIL 重算得出，NEVER 累加写入';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."LAST_REFUND_TIME" IS '最近一次退款汇总刷新时间';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."PAY_CENTER_ORDER_NO" IS '支付中心支付订单号，来自 requestPay 的同步应答；退款报文的原支付订单号取此列，缺它退款必失败';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."CHANNEL_ORDER_NO" IS '渠道订单号，即支付宝交易号（旧表 TRADE_NO）；属当前态关键标识，故留在本表';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."REQUEST_SIGN_SEQ" IS '我方签约流水号，取 ALIPAY_SIGN_INFO.AGREEMENT_CODE';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."CHANNEL_AGREEMENT_NO" IS '渠道协议号，取 ALIPAY_SIGN_INFO.CHANNEL_AGREEMENT_CODE；与上一列不是同一个号，销卡通知与退款只认这个';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."REQUEST_COUNT" IS '已发起支付请求次数；每次出网的请求与应答原文在 ALIPAY_PAY_CENTER_MSG_LOG，一次一行';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."NEXT_REQUEST_TIME" IS '下次允许重试支付时间';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."INVOICE" IS '发票状态；旧表 33 行实测全为 NULL、从未被写过，本表同样没有写入方，属占位列。接线前 MUST 先确认发票状态归谁维护，NEVER 假定它有值';
   COMMENT ON COLUMN "ALIPAY_PAY_TXN_DETAIL"."TRANS_TIME" IS '支付时刻，统一存14位yyyyMMddHHmmss（2026-09-20起，归一在PayTxnCallbackWriter.normalizeTransTime做）；报文原文留在ALIPAY_PAY_CALLBACK_LOG的TRANS_TIME与RAW_BODY；列仍是VARCHAR2因归一失败时原样入库，NEVER建成DATE也NEVER用TO_DATE查询；支付宝出行记录应答的payOrderNoDate取此列；只由支付回调写入且套NVL';
   COMMENT ON TABLE "ALIPAY_PAY_TXN_DETAIL"  IS '支付宝出行（小程序）渠道支付交易明细表；订单主表是 GATE_TXN_PAY，本表按 ORDER_NO 一对一挂在其上，只装支付侧当前态。报文原文在 ALIPAY_PAY_CENTER_MSG_LOG，对端回调在 ALIPAY_PAY_CALLBACK_LOG';

COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."ID" IS '主键，取 SEQ_ALIPAY_PHONE_CHANGE_LOG';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."THIRD_USER_ID" IS '支付宝用户标识，对应 ALIPAY_USER_INFO.THIRD_USER_ID';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."OLD_MSISDN" IS '变更前手机号，首次登记时可为空';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."NEW_MSISDN" IS '变更后手机号';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."OPER_TYPE" IS '操作类型：CHANGE_PHONE-更换手机号';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."OPER_TIME" IS '操作发生时间';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."OPERATOR" IS '操作人，系统触发填 SYSTEM';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."REMARK" IS '操作说明';
   COMMENT ON COLUMN "ALIPAY_PHONE_CHANGE_LOG"."CREATE_TMS" IS '记录落库时间';
   COMMENT ON TABLE "ALIPAY_PHONE_CHANGE_LOG"  IS '支付宝渠道用户手机号更换历史记录表，由 alipay-account-server 独占写入';

COMMENT ON COLUMN "ALIPAY_REFUND_LOG"."REFUND_SEQ" IS '退款流水号（主键）';
   COMMENT ON COLUMN "ALIPAY_REFUND_LOG"."THIRD_USER_ID" IS '支付宝用户ID';
   COMMENT ON COLUMN "ALIPAY_REFUND_LOG"."CARD_ID" IS '逻辑卡号';
   COMMENT ON COLUMN "ALIPAY_REFUND_LOG"."ORDER_NO" IS '原订单号';
   COMMENT ON COLUMN "ALIPAY_REFUND_LOG"."REFUND_AMOUNT" IS '退款金额（分）';
